import React from 'react';
import Seo from '../components/Seo';
import Icon from '../components/Icon';
import {capabilities,seoDetails} from '../data/site';
export default function Expertise(){return <>
 <Seo title="Compétences" path="/expertise" description="Compétences de Huriel Nguimbi via Beyond31 : React, Flutter, Supabase, UX, SEO technique, sécurité web et électronique de niveau BUT GEII."/>
 <section className="page-hero"><p className="eyebrow"><span/>Compétences</p><h1>Ce que je pratique,<br/><em>et jusqu’où.</em></h1><p>Je préfère préciser le terrain et le niveau plutôt que tout présenter comme une expertise équivalente.</p></section>
 <section className="expertise-list">{capabilities.map(c=><article className="expertise-row" key={c.n}><div className="expertise-icon"><Icon name={c.icon}/></div><div className="expertise-copy"><span>{c.level}</span><h2>{c.title}</h2><p>{c.desc}</p></div><div className="tool-cloud">{c.tools.map(t=><span key={t}>{t}</span>)}</div></article>)}</section>
 <section className="seo-panel"><div className="section-head"><div><p className="eyebrow"><span/>SEO & qualité</p><h2>Le site ne s’arrête pas à ce qu’on voit.</h2></div><p>Le référencement et la sécurité sont intégrés au développement, pas ajoutés à la fin pour cocher une case.</p></div><div className="seo-grid">{seoDetails.map(x=><article className="seo-card" key={x.title}><Icon name={x.icon}/><h3>{x.title}</h3><p>{x.text}</p></article>)}</div></section>
 </>}
